# Find simple bitwise predicate with offsets for top-left demo 10.
import itertools
obs=[[demo10[r][c]==4 for c in range(6)] for r in range(4)]
for a,b in itertools.product(range(8), repeat=2):
 for op in ['and0','andnonzero','xor0','equal']:
  pred=[]
  for r in range(4):
   row=[]
   for c in range(6):
    x,y=r+a,c+b
    val={'and0':(x&y)==0,'andnonzero':(x&y)!=0,'xor0':x==y,'equal':(x&y)==(x|y)}[op]
    row.append(val)
   pred.append(row)
  if pred==obs: print(a,b,op)
